INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF101', 'Introdução à Programação', 'Algoritmos, variáveis, estruturas de controle, funções e resolução de problemas.', 30, 30, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF102', 'Programação Orientada a Objetos', 'Classes, objetos, herança, polimorfismo, exceções e boas práticas de programação.', 30, 30, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF103', 'Estruturas de Dados', 'Listas, pilhas, filas, árvores, tabelas hash e análise de complexidade.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF104', 'Banco de Dados', 'Modelagem conceitual e relacional, normalização, SQL e transações.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF105', 'Engenharia de Software', 'Processos, requisitos, projeto, testes, manutenção e evolução de software.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF106', 'Redes de Computadores', 'Arquiteturas de redes, protocolos, endereçamento, roteamento e aplicações.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF107', 'Sistemas Operacionais', 'Processos, threads, memória, sistemas de arquivos e concorrência.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('IF108', 'Inteligência Artificial', 'Busca, representação de conhecimento, aprendizado de máquina e agentes.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('MA101', 'Cálculo Diferencial e Integral I', 'Limites, derivadas, aplicações de derivadas e integrais.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('MA102', 'Cálculo Diferencial e Integral II', 'Técnicas de integração, séries, funções de várias variáveis e integrais múltiplas.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('MA103', 'Álgebra Linear', 'Matrizes, sistemas lineares, espaços vetoriais, autovalores e autovetores.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('MA104', 'Matemática Discreta', 'Lógica, conjuntos, relações, indução, combinatória e grafos.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('MA105', 'Probabilidade', 'Variáveis aleatórias, distribuições, esperança, variância e teoremas limites.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('ES101', 'Estatística Descritiva', 'Organização de dados, medidas-resumo, gráficos e análise exploratória.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('ES102', 'Inferência Estatística', 'Estimação, intervalos de confiança, testes de hipóteses e regressão.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('FI101', 'Física Geral I', 'Cinemática, dinâmica, trabalho, energia e conservação do momento.', 60, 15, 5);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('FI102', 'Física Geral II', 'Oscilações, ondas, termodinâmica e introdução ao eletromagnetismo.', 60, 15, 5);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('QI101', 'Química Geral', 'Estrutura atômica, ligações químicas, estequiometria e soluções.', 45, 30, 5);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('QI102', 'Química Orgânica', 'Estrutura e reatividade de compostos orgânicos e mecanismos de reação.', 45, 30, 5);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('EE101', 'Circuitos Elétricos I', 'Leis de Kirchhoff, circuitos resistivos e análise de redes elétricas.', 45, 30, 5);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('EE102', 'Eletrônica Analógica', 'Diodos, transistores, amplificadores e circuitos eletrônicos básicos.', 45, 30, 5);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('AD101', 'Fundamentos de Administração', 'Teorias administrativas, funções gerenciais e estruturas organizacionais.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('AD102', 'Contabilidade Geral', 'Patrimônio, demonstrações contábeis, lançamentos e análise básica.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('AD103', 'Marketing', 'Comportamento do consumidor, segmentação, posicionamento e composto de marketing.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('LC101', 'Didática da Computação', 'Planejamento de ensino, metodologias ativas e ensino de computação.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('DS101', 'Fundamentos do Design', 'Princípios de composição, forma, cor, tipografia e processo de projeto.', 45, 15, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('DS102', 'Design de Interfaces', 'Arquitetura de informação, interação, prototipação e avaliação de interfaces.', 30, 30, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('EC101', 'Microeconomia', 'Oferta, demanda, teoria do consumidor, produção e estruturas de mercado.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('EC102', 'Macroeconomia', 'Produto, inflação, desemprego, política fiscal, monetária e setor externo.', 60, 0, 4);
INSERT INTO disciplina (codigo, nome, ementa, ch_teorica, ch_pratica, num_creditos) VALUES ('EC103', 'Econometria', 'Modelos de regressão, estimação, inferência e aplicações econômicas.', 45, 15, 4);
